-- Initial schema is managed by SQLAlchemy on API startup. This reference SQL documents relationships.
CREATE TABLE products (id SERIAL PRIMARY KEY, name VARCHAR(140) NOT NULL, category VARCHAR(80) NOT NULL, farmer_name VARCHAR(120) NOT NULL, description TEXT NOT NULL DEFAULT '', price NUMERIC(10,2) NOT NULL CHECK (price > 0), stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0), image_url VARCHAR(600) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cart_items (id SERIAL PRIMARY KEY, session_id VARCHAR(80) NOT NULL, product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity INTEGER NOT NULL CHECK (quantity > 0), UNIQUE(session_id, product_id));
CREATE TABLE orders (id SERIAL PRIMARY KEY, order_number VARCHAR(32) UNIQUE NOT NULL, customer_name VARCHAR(120) NOT NULL, email VARCHAR(254) NOT NULL, address TEXT NOT NULL, total NUMERIC(10,2) NOT NULL CHECK (total >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id SERIAL PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id INTEGER REFERENCES products(id) ON DELETE SET NULL, product_name VARCHAR(140) NOT NULL, unit_price NUMERIC(10,2) NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0));
